import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Report.
 *
 * @stability experimental
 */
export interface IReportRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Report resource.
     */
    readonly reportRef: ReportReference;
}
/**
 * A reference to a Report resource.
 *
 * @struct
 * @stability external
 */
export interface ReportReference {
    /**
     * The Arn of the Report resource.
     */
    readonly reportArn: string;
}
